/* host_api.c: the loader's F3Api, in software, for running light apps on the PC. 256 x 402 RGB565 canvas, all drawing clipped.
 * Text uses the 8x12 glyph table from kbd_font.h (generated by genfont.py: right cell size, not the watch's glyph shapes).
 * Build apps with -finput-charset=UTF-8 -fexec-charset=ISO-8859-1, like tools/appcc.py does, so accented strings are Latin-1 bytes. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "kbd_font.h"
#include "host_api.h"

#define MAX_FILES 8
#define FRAME_MS 33

static u16 canvas[F3_W * F3_H];
static F3Api api;
static F3App *app;
static unsigned clock_ms = 1000;
static int quiet, running, was_pressed, vib_count, violations, live_blocks, pt_flag, battery_pct = 87, tod_base, tod_at_ms;
static char data_dir[300];
static FILE *files[MAX_FILES];

static void span(u16 *buf, int y, int x0, int x1, u16 c) {          /* inclusive horizontal run */
    if (y < 0 || y >= F3_H) return;
    if (x0 < 0) x0 = 0;
    if (x1 >= F3_W) x1 = F3_W - 1;
    for (int x = x0; x <= x1; x++) buf[y * F3_W + x] = c;
}

static void *h_malloc(u32 n) { void *p = calloc(1, n ? n : 1); if (p) live_blocks++; return p; }
static void h_free(void *p) { if (p) { live_blocks--; free(p); } }
static u32 h_ticks(void) { return clock_ms; }
static void h_vibrate(int id) { vib_count++; if (!quiet) fprintf(stderr, "[sim] vibrate(%d) at %u ms\n", id, clock_ms); }

static void h_rect(u16 *b, int x, int y, int w, int h, u16 c) {
    if (w < 0 || h < 0) violations++;
    for (int j = 0; j < h; j++) span(b, y + j, x, x + w - 1, c);
}
static void h_rrect(u16 *b, int x, int y, int w, int h, int r, u16 c) {
    if (w < 0 || h < 0 || r < 0) { violations++; return; }
    if (2 * r > w) r = w / 2;
    if (2 * r > h) r = h / 2;
    for (int j = 0; j < h; j++) {
        int inset = 0;                                                  /* how far this row is pulled in by the corner arcs */
        int d = j < r ? r - j : (j >= h - r ? j - (h - r - 1) : 0);     /* vertical distance into a corner band */
        if (d) { while (inset < r && (r - inset) * (r - inset) + d * d > r * r + r) inset++; }
        span(b, y + j, x + inset, x + w - 1 - inset, c);
    }
}
static void h_disc(u16 *b, int cx, int cy, int r, u16 c) {
    if (r < 0) { violations++; return; }
    for (int j = -r; j <= r; j++) {
        int half = 0; while ((half + 1) * (half + 1) + j * j <= r * r) half++;
        span(b, cy + j, cx - half, cx + half, c);
    }
}
static const u8 *glyph(int cp) {
    if (cp >= 32 && cp <= 126) return kbd_font[cp - 32];
    for (int i = 0; i < (int)(sizeof kbd_font_extra_cp / sizeof kbd_font_extra_cp[0]); i++)
        if (kbd_font_extra_cp[i] == cp && KBD_FONT_N_ASCII + i < (int)(sizeof kbd_font / sizeof kbd_font[0])) return kbd_font[KBD_FONT_N_ASCII + i];
    return kbd_font['?' - 32];
}
static void h_text(u16 *b, int x, int y, const char *s, int sc, u16 c) {
    if (!s || sc < 1 || sc > 12) { violations++; if (!s) return; if (sc < 1) return; sc = 12; }
    for (; *s; s++, x += 8 * sc) {
        const u8 *g = glyph((u8)*s);
        for (int row = 0; row < 12; row++) for (int col = 0; col < 8; col++)
            if (g[row] & (0x80 >> col)) for (int j = 0; j < sc; j++) span(b, y + row * sc + j, x + col * sc, x + col * sc + sc - 1, c);
    }
}
static void h_ctext(u16 *b, int cx, int y, const char *s, int sc, u16 c) { if (!s) { violations++; return; } h_text(b, cx - (int)strlen(s) * 4 * sc, y, s, sc, c); }
static void h_num(u16 *b, int x, int y, int v, int sc, u16 c) { char t[16]; snprintf(t, sizeof t, "%d", v); h_text(b, x, y, t, sc, c); }

static int h_fopen(const char *path, const char *mode) {
    const char *slash = path ? strrchr(path, '/') : NULL, *base = slash ? slash + 1 : path;
    char full[420];
    if (!base || !*base || !mode) { violations++; return -1; }
    snprintf(full, sizeof full, "%s/%s", data_dir, base);
    FILE *f = fopen(full, mode[0] == 'w' ? "wb" : "rb");
    if (!f) return -1;
    for (int i = 0; i < MAX_FILES; i++) if (!files[i]) { files[i] = f; return i; }
    fclose(f); return -1;
}
static int valid_fd(int fd) { if (fd < 0 || fd >= MAX_FILES || !files[fd]) { violations++; return 0; } return 1; }
static int h_fread(int fd, void *buf, u32 n) { return valid_fd(fd) ? (int)fread(buf, 1, n, files[fd]) : -1; }
static int h_fwrite(int fd, const void *buf, u32 n) { return valid_fd(fd) ? (int)fwrite(buf, 1, n, files[fd]) : -1; }
static int h_fclose(int fd) { if (!valid_fd(fd)) return -1; fclose(files[fd]); files[fd] = NULL; return 0; }

static struct tm today;
static void h_time(F3Time *t) {
    int s = (tod_base + (int)(clock_ms - (unsigned)tod_at_ms) / 1000) % 86400;
    t->year = today.tm_year + 1900; t->month = today.tm_mon + 1; t->day = today.tm_mday; t->wday = today.tm_wday;     /* wday: 0 = Sunday here; the real firmware's numbering is not documented */
    t->hour = s / 3600; t->min = s / 60 % 60; t->sec = s % 60;
}
static int h_battery(void) { return battery_pct; }

int host_init(const char *dir, int clock_secs) {
    time_t now = time(NULL); localtime_r(&now, &today);
    snprintf(data_dir, sizeof data_dir, "%s", dir && *dir ? dir : ".");
    memset(&api, 0, sizeof api);
    api.version = F3_API_VERSION; api.fb = canvas; api.w = F3_W; api.h = F3_H;
    api.malloc = h_malloc; api.free = h_free; api.ticks = h_ticks; api.vibrate = h_vibrate;
    api.rect = h_rect; api.rrect = h_rrect; api.disc = h_disc; api.text = h_text; api.ctext = h_ctext; api.num = h_num;
    api.fopen = h_fopen; api.fread = h_fread; api.fwrite = h_fwrite; api.fclose = h_fclose;
    api.lang_pt = (u32)pt_flag; api.time = h_time; api.battery = h_battery;
    host_set_clock(clock_secs);
    app = f3app_main(&api); running = app != NULL;
    return app ? 0 : 1;
}
int host_step(int pressed, int x, int y) {
    if (!running) return 0;
    int tap = !pressed && was_pressed;
    was_pressed = pressed; clock_ms += FRAME_MS;
    running = app->tick(app, pressed, x, y, tap);
    return running;
}
const u16 *host_fb(void) { return canvas; }
void host_close(void) { if (running && app && app->close) app->close(app); running = 0; }
int host_vibrations(void) { return vib_count; }
int host_violations(void) { return violations; }
int host_leaks(void) { return live_blocks; }
void host_set_lang(int pt) { pt_flag = pt; api.lang_pt = (u32)pt; }
void host_set_battery(int pct) { battery_pct = pct; }
void host_set_clock(int secs) { tod_base = secs; tod_at_ms = (int)clock_ms; }

static unsigned rng_state = 1;
static unsigned rnd(void) { rng_state = rng_state * 1664525u + 1013904223u; return rng_state >> 8; }
int host_monkey(unsigned seed) {
    rng_state = seed * 2654435761u + 1; quiet = 1;
    for (int i = 0; i < 6000 && running; i++) {
        int kind = (int)(rnd() % 10), x = (int)(rnd() % F3_W), y = (int)(rnd() % F3_H);
        if (kind < 4) { host_step(1, x, y); host_step(0, x, y); }                                   /* tap */
        else if (kind < 7) {                                                                          /* swipe */
            int x2 = x + (int)(rnd() % 120) - 60, y2 = y + (int)(rnd() % 120) - 60;
            for (int s = 0; s <= 5; s++) host_step(1, x + (x2 - x) * s / 5, y + (y2 - y) * s / 5);
            host_step(0, x2, y2);
        } else if (kind < 9) { int n = (int)(rnd() % 40); for (int s = 0; s < n; s++) host_step(1, x, y); host_step(0, x, y); }   /* hold */
        else { int n = (int)(rnd() % 30); for (int s = 0; s < n; s++) host_step(0, x, y); }          /* idle */
        if (i == 3000) host_set_lang(!pt_flag);
    }
    int alive = running, bad = !alive || violations; host_close();
    printf("monkey seed %u: running=%d violations=%d vibrations=%d leaks=%d\n", seed, alive, violations, vib_count, live_blocks);
    return bad;
}
